import { useSearchParams } from "react-router";

const LEVELS = new Set(["all", "beginner", "intermediate"]);

export function parsePage(raw, totalPages) {
  const n = Number(raw);
  return Number.isInteger(n) && n >= 1 && n <= totalPages ? n : 1;
}

export function CourseList({ courses, pageSize = 10 }) {
  const [params, setParams] = useSearchParams();
  const level = LEVELS.has(params.get("level")) ? params.get("level") : "all";
  const filtered = level === "all" ? courses : courses.filter((c) => c.level === level);
  const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize));
  const page = parsePage(params.get("page"), totalPages);

  function goTo(next) {
    setParams({ level, page: String(next) });   // canonical values only.
  }
  const shown = filtered.slice((page - 1) * pageSize, page * pageSize);
  return <p>Page {page} of {totalPages}, {shown.length} courses</p>;
}
